type result = {a: int, c: int, g: int, t: int}
fun nucleotideCounts (strand: string) : result =
  foldl
    (fn (x, {a, c, g, t}) =>
       case x of
         #"A" => {a = a + 1, c = c, g = g, t = t}
       | #"C" => {a = a, c = c + 1, g = g, t = t}
       | #"G" => {a = a, c = c, g = g + 1, t = t}
       | #"T" => {a = a, c = c, g = g, t = t + 1}
       | _ => raise Fail "Invalid nucleotide in strand")
       {a = 0, c = 0, g = 0, t = 0} (String.explode strand)

fun nucleotideCounts (strand: string): {a: int, c: int, g: int, t: int} =
  let fun count (#"G", {a, c, g, t}) = {a=a, c=c, g=g+1, t=t}
        | count (#"A", {a, c, g, t}) = {a=a+1, c=c, g=g, t=t}
        | count (#"C", {a, c, g, t}) = {a=a, c=c+1, g=g, t=t}
        | count (#"T", {a, c, g, t}) = {a=a, c=c, g=g, t=t+1}
        | count _ = raise Fail "Invalid nucleotide in strand"
  in foldl count {a=0,c=0,g=0,t=0} (explode strand)
  end

"fun inc n = n + 1;
fun dec n = n - 1;
fun compound 0 f x = x 
  | compound n f x = compound (n-1) f (f x)
fun exp b e = compound e (fn x => b*x) 1;
fun positive xs =
  let
    fun positive' [] p = rev p
      | positive' (y::ys) p =
        if y < 0 then
          positive' ys p
        else
          positive' ys (y :: p)
  in
    positive' xs []
  end;
fun lessThan b d =
if d >= b then true else false;
fun rebase (inBase: int, outBase: int, digits: int list) =
if inBase <= 1 orelse outBase <= 1
orelse length (positive digits) <> length digits
orelse List.filter (lessThan inBase) digits <> []
then NONE else
let
  val count = ref (length digits);
  val index = ref 0;
  val bt = ref 0;
  val bo = ref [];
in
  while !count > 0 do(
    bt := !bt + ((exp inBase (!count-1))*List.nth(digits,!index));
    index := inc(!index);
    count := dec(!count));
  while !bt > 0 do(
    bo := (!bt mod outBase)::(!bo);
    bt := (!bt div outBase));
if !bo = [] then NONE else SOME (!bo)
end;
"
